```python
def fizzbuzz(n: int) -> list[str]:
    """Return FizzBuzz list for 1 to n (or [] if n < 1)."""
    if n < 1:
        return []  # empty for invalid input
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")  # multiple of both
        elif i % 3 == 0:
            result.append("Fizz")  # multiple of 3 only
        elif i % 5 == 0:
            result.append("Buzz")  # multiple of 5 only
        else:
            result.append(str(i))  # plain number
    return result
```

```python
def sieve_primes(n: int) -> list[int]:
    """Return all primes <= n using the Sieve of Eratosthenes."""
    if n < 2:
        return []  # no primes below 2
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n+1, i):
                is_prime[j] = False  # mark multiples
    return [i for i in range(n+1) if is_prime[i]]
```

```python
def flatten(nested: list) -> list:
    """Return a flat list of all non-list elements from nested, left-to-right."""
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))  # recurse on nested list
        else:
            result.append(item)           # keep non-list as single element
    return result
```

```python
def rotate_matrix(matrix: list[list[int]]) -> list[list[int]]:
    """Rotate an n x n matrix 90 degrees clockwise, returning a new matrix."""
    if not matrix:
        return []
    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # new row is old column, new column is n-1 minus old row
            result[j][n - 1 - i] = matrix[i][j]
    return result
```

```python
def leftmost_index(arr: list[int], target: int) -> int:
    """Return the leftmost index of target in sorted arr, or -1 if absent."""
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1  # search right half
        else:
            high = mid - 1  # search left half (including mid)
    if low < len(arr) and arr[low] == target:
        return low
    return -1
```

```python
def roman_to_int(s: str) -> int:
    """Convert valid Roman numeral (1-3999) to integer using standard and subtractive notation."""
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    res = 0
    for i in range(len(s)):
        # subtract if current value smaller than next (subtractive pair)
        if i + 1 < len(s) and values[s[i]] < values[s[i + 1]]:
            res -= values[s[i]]
        else:
            res += values[s[i]]
    return res
```

```python
def max_subarray_sum(nums: list[int]) -> int:
    """Return max sum of any contiguous subarray using Kadane's algorithm."""
    if not nums:
        raise ValueError("nums cannot be empty")
    max_current = max_global = nums[0]
    for num in nums[1:]:
        max_current = max(num, max_current + num)  # extend or start new
        if max_current > max_global:
            max_global = max_current
    return max_global
```

```python
def longest_common_subsequence(a: str, b: str) -> int:
    """Return length of longest common subsequence of a and b."""
    if len(a) > len(b):
        a, b = b, a  # ensure len(a) <= len(b) for O(min) space
    m, n = len(a), len(b)
    prev = [0] * (m + 1)
    curr = [0] * (m + 1)
    for j in range(1, n + 1):
        for i in range(1, m + 1):
            if a[i-1] == b[j-1]:
                curr[i] = prev[i-1] + 1
            else:
                curr[i] = max(prev[i], curr[i-1])
        prev, curr = curr, prev  # reuse arrays, O(min(len(a), len(b))) space
    return prev[m]
```

```python
def edit_distance(a: str, b: str) -> int:
    """Return the Levenshtein edit distance between strings a and b."""
    m, n = len(a), len(b)
    # DP table: dp[i][j] = distance for a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i  # deletions
    for j in range(n + 1):
        dp[0][j] = j  # insertions
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],   # delete
                                   dp[i][j-1],   # insert
                                   dp[i-1][j-1]) # substitute
    return dp[m][n]
```

```python
import heapq

def shortest_paths(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, int]:
    """Compute shortest path distances from source using Dijkstra's algorithm."""
    # Collect all nodes including those appearing only as neighbors
    nodes = set(graph.keys())
    for neighbors in graph.values():
        for neigh, _ in neighbors:
            nodes.add(neigh)
    # Initialize distances
    dist = {node: float('inf') for node in nodes}
    dist[source] = 0
    # Priority queue for Dijkstra
    pq = []
    heapq.heappush(pq, (0, source))
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u in graph:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
    # Return only reachable nodes
    return {k: v for k, v in dist.items() if v < float('inf')}
```

```python
def count_n_queens(n: int) -> int:
    """Count solutions to n-queens using backtracking."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    def backtrack(row, cols, diag1, diag2):
        if row == n:
            return 1  # found valid placement
        count = 0
        for col in range(n):
            if col not in cols and (row - col) not in diag1 and (row + col) not in diag2:
                cols.add(col)
                diag1.add(row - col)
                diag2.add(row + col)
                count += backtrack(row + 1, cols, diag1, diag2)
                cols.remove(col)
                diag1.remove(row - col)
                diag2.remove(row + col)
        return count
    return backtrack(0, set(), set(), set())
```
